using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Tool implementations ---

/// <summary>Tools for searching the web and taking research notes.</summary>
static class ResearchTools
{
    private static readonly List<string> _notes = [];
    private static readonly HttpClient _http = new();

    [Description("Search the web for information on a query. Returns a list of result snippets.")]
    public static async Task<string> SearchWeb(
        [Description("The search query")] string query)
    {
        Console.ForegroundColor = ConsoleColor.DarkCyan;
        Console.WriteLine($"  [Tool] Searching the web for: \"{query}\"");
        Console.ResetColor();

        try
        {
            // Use Wikipedia API as a freely available search source
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://en.wikipedia.org/w/api.php?action=query&list=search&srsearch={encoded}&format=json&utf8=1&srlimit=5";
            var response = await _http.GetStringAsync(url);

            using var doc = JsonDocument.Parse(response);
            var results = doc.RootElement.GetProperty("query").GetProperty("search");

            var sb = new StringBuilder();
            int i = 1;
            foreach (var result in results.EnumerateArray())
            {
                var title = result.GetProperty("title").GetString();
                // Strip HTML tags from snippet
                var snippet = System.Text.RegularExpressions.Regex.Replace(
                    result.GetProperty("snippet").GetString() ?? "", "<.*?>", "");
                sb.AppendLine($"{i}. **{title}**: {snippet}");
                i++;
            }

            return sb.Length > 0
                ? sb.ToString()
                : "No results found. Try a different query.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try rephrasing the query.";
        }
    }

    [Description("Save a research note. Use this to record important findings as you research.")]
    public static string SaveNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.ForegroundColor = ConsoleColor.DarkYellow;
        Console.WriteLine($"  [Tool] Note saved (#{_notes.Count})");
        Console.ResetColor();
        return $"Note #{_notes.Count} saved successfully.";
    }

    [Description("Retrieve all saved research notes.")]
    public static string GetNotes()
    {
        Console.ForegroundColor = ConsoleColor.DarkYellow;
        Console.WriteLine($"  [Tool] Retrieving {_notes.Count} note(s)");
        Console.ResetColor();

        if (_notes.Count == 0)
            return "No notes saved yet.";

        var sb = new StringBuilder();
        for (int i = 0; i < _notes.Count; i++)
            sb.AppendLine($"Note #{i + 1}: {_notes[i]}");
        return sb.ToString();
    }
}

// --- Main program ---

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY");
if (string.IsNullOrEmpty(apiKey))
{
    Console.ForegroundColor = ConsoleColor.Red;
    Console.WriteLine("Error: Set the OPENAI_API_KEY environment variable.");
    Console.ResetColor();
    return 1;
}

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

IChatClient client = new OpenAIClient(apiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var tools = new AIFunctionFactory[] { }; // placeholder; tools come from ChatOptions
var chatOptions = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(ResearchTools.SearchWeb),
        AIFunctionFactory.Create(ResearchTools.SaveNote),
        AIFunctionFactory.Create(ResearchTools.GetNotes),
    ]
};

var systemPrompt = """
    You are a research agent. Your job is to research a topic the user provides by:
    1. Searching the web multiple times with varied queries to gather broad information.
    2. Saving key findings as notes using the SaveNote tool.
    3. After gathering enough information, retrieving your notes and synthesizing
       a well-structured summary for the user.

    Always search at least 2-3 different queries, save the most important facts,
    then present a final summary with your notes as the foundation.
    """;

List<ChatMessage> messages = [new(ChatRole.System, systemPrompt)];

Console.ForegroundColor = ConsoleColor.Green;
Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║        AI Research Agent (.NET 10)       ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.ResetColor();
Console.WriteLine("Enter a topic to research (or 'quit' to exit):\n");

while (true)
{
    Console.ForegroundColor = ConsoleColor.White;
    Console.Write("> ");
    Console.ResetColor();

    var input = Console.ReadLine();
    if (string.IsNullOrWhiteSpace(input) || input.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    messages.Add(new(ChatRole.User, $"Research this topic and provide a summary: {input}"));

    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine("\nResearching... (the agent will search the web and take notes)\n");
    Console.ResetColor();

    var response = await client.GetResponseAsync(messages, chatOptions);

    // Append all response messages to history
    foreach (var msg in response.Messages)
        messages.Add(msg);

    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.WriteLine("\n── Research Summary ─────────────────────────");
    Console.ResetColor();

    // Print the final text content from the response
    Console.WriteLine(response.Text);
    Console.WriteLine();
}

Console.WriteLine("Goodbye!");
return 0;

