    Console.WriteLine($"  [Tool] Retrieving {notes.Count} note(s)");
    Console.ResetColor();

    if (notes.Count == 0)
        return "No notes saved yet.";

    var sb = new StringBuilder();
    for (int i = 0; i < notes.Count; i++)
        sb.AppendLine($"Note #{i + 1}: {notes[i]}");
    return sb.ToString();
}

